// т.к. имена переменных режима (brutal/glass/minimal) задаются темой.
import { useMemo, useState } from 'react';

const PAGE_SIZE = 10;

export type UserStatus = 'active' | 'disabled';

export type UserRow = {
  id: string | number;
  name: string;
  role: string;
  status: UserStatus;
};

type UsersTableProps = {
  users: UserRow[];
  caption?: string;
};

export default function UsersTable({ users, caption = 'Пользователи' }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(Math.max(page, 1), pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  return (
    <section
      className="jx-stack"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3, 12px)' }}
    >
      <div className="jx-table-wrap">
        <table className="jx-table">
          <caption className="jx-table__caption">{caption}</caption>
          <thead className="jx-table__head">
            <tr>
              <th scope="col">Имя</th>
              <th scope="col">Роль</th>
              <th scope="col">Статус</th>
            </tr>
          </thead>
          <tbody className="jx-table__body">
            {rows.length === 0 ? (
              <tr>
                <td colSpan={3} className="jx-table__empty">
                  Нет пользователей
                </td>
              </tr>
            ) : (
              rows.map((user) => (
                <tr key={user.id}>
                  <td>{user.name}</td>
                  <td>{user.role}</td>
                  <td>
                    <span
                      className={
                        user.status === 'active'
                          ? 'jx-badge jx-badge--success'
                          : 'jx-badge jx-badge--danger'
                      }
                    >
                      {user.status === 'active' ? 'Активен' : 'Отключён'}
                    </span>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <nav
        className="jx-pagination"
        aria-label="Навигация по страницам"
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--jx-space-2, 8px)',
